int basic_callable(int x) {
    return x * 2;
}

// Function pointer implementation
using FuncPtr = int(*)(int);
FuncPtr fp = &basic_callable;
int result = fp(5);


class StatefulFunctor {
    int factor_;
public:
    // Functors maintain internal state
    explicit StatefulFunctor(int f) : factor_(f) {}

    // Overloaded function call operator
    // Compiler treats this as a member function call (implicit 'this')
    int operator()(int x) const {
        return x * factor_;
    }
};

StatefulFunctor m(10);
int res = m(5); // Invocation looks like a function call
